import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { GAP_RANGES } from "@/lib/rest-advantage-evidence";
import {
  HOME_BAR_COUNTERFACTUAL,
  liftOverBaseline,
  RESTED_AT_HOME,
  RESTED_ON_ROAD,
  RESTED_ON_ROAD_BY_ERA,
  REST_SPLIT_BASELINE,
  REST_SPLIT_SAMPLE,
  THIN_SAMPLE_GAMES,
} from "@/lib/rest-split-facts";

/**
 * These constants are what the method page publishes. They are generated by
 * `scripts/measure_uncalled_half.ts` and hand-mirrored into `rest-split-facts.ts`, so this
 * test is what stops the two drifting apart.
 *
 * It is the guard the page did not have. "44.4% across 7,224 games" sat in prose describing a
 * population the site had stopped publishing, and nothing failed.
 */
const facts = JSON.parse(
  readFileSync(join(process.cwd(), "ml", "rest_split_facts.json"), "utf8")
);

describe("rest split facts mirror the generated measurement", () => {
  it("the sample matches", () => {
    expect(REST_SPLIT_SAMPLE).toEqual(facts.sample);
  });

  it("the venue baseline matches", () => {
    expect(REST_SPLIT_BASELINE).toEqual(facts.baseline);
  });

  it("the rested-at-home row matches, gap sizes included", () => {
    expect(RESTED_AT_HOME).toEqual(facts.restedAtHome);
  });

  it("the rested-on-road row matches, gap sizes included", () => {
    expect(RESTED_ON_ROAD).toEqual(facts.restedOnRoad);
  });

  it("the home-bar counterfactual matches", () => {
    expect(HOME_BAR_COUNTERFACTUAL).toEqual(facts.counterfactual);
  });

  it("the era rows match, gap sizes included", () => {
    expect(RESTED_ON_ROAD_BY_ERA).toEqual(facts.restedOnRoadByEra);
  });
});

/**
 * The era rows exist because two retired claims treated a pooled 41-season rate as timeless.
 * These pin the shape of the replacement rather than only its values.
 */
describe("the road row by era", () => {
  const [all, last10, last5] = RESTED_ON_ROAD_BY_ERA;

  it("opens on the full population, so the eras are read as a subset of it", () => {
    expect(all.games).toBe(RESTED_ON_ROAD.games);
    expect(all.winPct).toBe(RESTED_ON_ROAD.winPct);
    expect(all.seasons).toBe(REST_SPLIT_SAMPLE.seasons);
  });

  it("narrows monotonically", () => {
    expect(last10.games).toBeLessThan(all.games);
    expect(last5.games).toBeLessThan(last10.games);
  });

  /**
   * The finding, and the reason the raw rate alone is not it: the road row has climbed nearly
   * seven points, and the road baseline climbed with it. Quoting 49.3% without 44.7% beside it
   * would restate the mistake this whole frame exists to fix.
   */
  it("shows the raw rate drifting upward", () => {
    expect(last10.winPct).toBeGreaterThan(all.winPct);
    expect(last5.winPct).toBeGreaterThan(last10.winPct);
  });

  it("shows the baseline drifting with it, which is most of the movement", () => {
    expect(last10.roadBaselinePct).toBeGreaterThan(all.roadBaselinePct);
    expect(last5.roadBaselinePct).toBeGreaterThan(last10.roadBaselinePct);

    // Baseline movement accounts for the majority of the raw movement.
    const rawMove = last5.winPct - all.winPct;
    const baseMove = last5.roadBaselinePct - all.roadBaselinePct;
    expect(baseMove).toBeGreaterThan(rawMove / 2);
  });

  it("states each era's lift against that era's own baseline", () => {
    for (const era of RESTED_ON_ROAD_BY_ERA) {
      expect(era.liftPp).toBe(Math.round((era.winPct - era.roadBaselinePct) * 10) / 10);
    }
  });

  /**
   * The gap size that refutes "no threshold rescues it" in the modern game, and the ones thin
   * enough that the page must mute them. Pinned so neither can drift silently.
   */
  it("carries a modern gap size above even on a sample worth printing", () => {
    const medium = last5.ranges.find((r) => r.key === "medium")!;

    expect(medium.winPct).toBeGreaterThan(50);
    expect(medium.games).toBeGreaterThanOrEqual(THIN_SAMPLE_GAMES);
  });

  it("marks the large size of the last ten and last five seasons as too thin to quote", () => {
    for (const era of [last10, last5]) {
      expect(era.ranges.find((r) => r.key === "large")!.games).toBeLessThan(THIN_SAMPLE_GAMES);
    }
  });
});

describe("the home-bar counterfactual", () => {
  /**
   * The load-bearing fact: folding home court into the score and letting it pick lands BELOW
   * simply backing the home team every time. If this ever flips, the argument for counting the
   * two rows separately needs rewriting rather than restating.
   */
  it("does not beat picking the home team in every game", () => {
    expect(HOME_BAR_COUNTERFACTUAL.accuracyPct).toBeLessThan(
      HOME_BAR_COUNTERFACTUAL.alwaysHomePct
    );
  });

  it("still makes road picks, and loses most of them", () => {
    const { roadCalls, roadLosses } = HOME_BAR_COUNTERFACTUAL;

    expect(roadCalls).toBeGreaterThan(0);
    expect(roadLosses / roadCalls).toBeGreaterThan(0.5);
  });

  it("uses the whole population, so its coverage is not comparable to a decided-only rate", () => {
    expect(HOME_BAR_COUNTERFACTUAL.calls).toBeGreaterThan(REST_SPLIT_SAMPLE.decided);
    expect(HOME_BAR_COUNTERFACTUAL.calls).toBeLessThanOrEqual(REST_SPLIT_SAMPLE.scoredGames);
  });
});

describe("rest split facts are internally consistent", () => {
  it("the two rows account for every decided game", () => {
    expect(RESTED_AT_HOME.games + RESTED_ON_ROAD.games).toBe(REST_SPLIT_SAMPLE.decided);
  });

  it("every scored game is decided or neutral, and nothing is both", () => {
    expect(REST_SPLIT_SAMPLE.decided + REST_SPLIT_SAMPLE.neutral).toBe(
      REST_SPLIT_SAMPLE.scoredGames
    );
  });

  it("the baseline covers the whole population, not only the published row", () => {
    // The point of the baseline: it is the widest set, wider than either row.
    expect(REST_SPLIT_BASELINE.games).toBe(REST_SPLIT_SAMPLE.scoredGames);
    expect(REST_SPLIT_BASELINE.games).toBeGreaterThan(RESTED_AT_HOME.games);
  });

  it("states both venue baselines from the same counts", () => {
    const { games, homeWins, homeWinPct, roadWinPct } = REST_SPLIT_BASELINE;
    expect(homeWinPct).toBe(Math.round((homeWins / games) * 1000) / 10);
    expect(roadWinPct).toBe(Math.round(((games - homeWins) / games) * 1000) / 10);
  });

  it("splits every row into the site's three gap sizes, each game in exactly one", () => {
    for (const row of [RESTED_AT_HOME, RESTED_ON_ROAD, ...RESTED_ON_ROAD_BY_ERA]) {
      expect(row.ranges.map((r) => r.key)).toEqual(GAP_RANGES.map((range) => range.key));
      expect(row.ranges.reduce((sum, r) => sum + r.games, 0)).toBe(row.games);
      expect(row.ranges.reduce((sum, r) => sum + r.wins, 0)).toBe(row.wins);
    }
  });

  it("states each gap size's rate from its own counts", () => {
    for (const row of [RESTED_AT_HOME, RESTED_ON_ROAD, ...RESTED_ON_ROAD_BY_ERA]) {
      for (const r of row.ranges) {
        expect(r.wins).toBeLessThanOrEqual(r.games);
        expect(r.winPct).toBe(Math.round((r.wins / r.games) * 1000) / 10);
      }
    }
  });
});

/**
 * The two claims the page published that the measurement refuted. Pinned as tests so the
 * sentences cannot come back without the data coming back with them.
 */
describe("the claims that had to be retired", () => {
  it("a rest gap DOES lift the road row past even, so 'no threshold rescues it' is false", () => {
    const rescued = RESTED_ON_ROAD_BY_ERA.flatMap((era) =>
      era.ranges.filter((r) => r.winPct > 50 && r.games >= THIN_SAMPLE_GAMES)
    );

    expect(rescued.length).toBeGreaterThan(0);
  });

  it("no pooled road gap size reaches even, so the rescue is a recent-era finding only", () => {
    for (const r of RESTED_ON_ROAD.ranges) expect(r.winPct).toBeLessThan(50);
  });
});

describe("liftOverBaseline", () => {
  it("signs the distance from the side's own baseline", () => {
    expect(liftOverBaseline(RESTED_AT_HOME.winPct, REST_SPLIT_BASELINE.homeWinPct)).toBe(1.3);
    expect(liftOverBaseline(RESTED_ON_ROAD.winPct, REST_SPLIT_BASELINE.roadWinPct)).toBe(2.2);
  });

  it("keeps one decimal rather than leaking float error", () => {
    expect(liftOverBaseline(63.1, 59.9)).toBe(3.2);
    expect(liftOverBaseline(63.1, 59.9).toString()).toBe("3.2");
  });
});
